using Itacr.Application.Orders.CreateOrder;

namespace Itacr.Application.Orders.CreatePickupOrder;

/// <summary>
/// The pickup order of a customer without an account. <paramref name="ClientOrderId"/> is generated by the customer's
/// device and identifies the order across retries; prices are never part of the request, they come from the menu. A request
/// that also carries a table, a waiter, or a channel is read as if it did not: those are decided by the server.
/// </summary>
public sealed record CreatePickupOrderCommand(Guid ClientOrderId, string? Name, string? Phone, IReadOnlyList<CreateOrderItem> Items);
